static int rp1_clock_gate_model_read32(
    void *context,
    u32 region,
    u32 offset,
    u32 *value
)
{
    rp1_clock_gate_io_model *model =
        (rp1_clock_gate_io_model *)context;
    if (model == (rp1_clock_gate_io_model *)0
        || model->registers == (volatile u32 *)0
        || value == (u32 *)0 || region != 0u
        || (offset & (sizeof(u32) - 1u)) != 0u
        || offset >= 0x10038u) {
        return 0;
    }
    ++model->read_calls;
    if (model->read_calls == model->fail_read_call) {
        return 0;
    }
    *value = model->registers[offset / sizeof(u32)];
    return 1;
}

static int rp1_clock_gate_model_write32(
    void *context,
    u32 region,
    u32 offset,
    u32 value
)
{
    rp1_clock_gate_io_model *model =
        (rp1_clock_gate_io_model *)context;
    if (model == (rp1_clock_gate_io_model *)0
        || model->registers == (volatile u32 *)0
        || region != 0u || (offset & (sizeof(u32) - 1u)) != 0u
        || offset >= 0x10038u) {
        return 0;
    }
    ++model->write_calls;
    if (model->write_calls == model->fail_write_call) {
        return 0;
    }
    model->registers[offset / sizeof(u32)] = value;
    return 1;
}

static int rp1_audio_out_clock_ready(
    void *context,
    u16 provider_node_index,
    u32 clock_id,
    u32 expected_rate_hz
)
{
    rp1_audio_out_readiness_model *model =
        (rp1_audio_out_readiness_model *)context;
    if (model == (rp1_audio_out_readiness_model *)0) {
        return 0;
    }
    ++model->clock_checks;
    return model->clock_ready == 1u
        && provider_node_index == 1u
        && clock_id == OS_PI5_RP1_CLOCK_ID_AUDIO_OUT
        && expected_rate_hz == OS_PI5_RP1_AUDIO_OUT_CLOCK_HZ;
}

static int rp1_audio_out_interrupt_ready(
    void *context,
    u32 interrupt_id,
    u32 channel,
    u32 owner
)
{
    rp1_audio_out_readiness_model *model =
        (rp1_audio_out_readiness_model *)context;
    if (model == (rp1_audio_out_readiness_model *)0) {
        return 0;
    }
    ++model->interrupt_checks;
    return model->interrupt_ready == 1u
        && interrupt_id == OS_PI5_RP1_DMA_INTERRUPT_ID
        && channel == 3u && owner == 77u;
}

static int rp1_audio_out_cache_ready(
    void *context,
    const os_pi5_rp1_dma_lli_stage *stage,
    u32 owner
)
{
    rp1_audio_out_readiness_model *model =
        (rp1_audio_out_readiness_model *)context;
    if (model == (rp1_audio_out_readiness_model *)0
        || stage == (const os_pi5_rp1_dma_lli_stage *)0) {
        return 0;
    }
    ++model->cache_checks;
    return model->cache_ready == 1u
        && stage->active == 1u && stage->owner == owner;
}

static int rp1_audio_out_model_read32(
    void *context,
    u32 region,
    u32 offset,
    u32 *value
)
{
    rp1_audio_out_register_model *model =
        (rp1_audio_out_register_model *)context;
    if (model == (rp1_audio_out_register_model *)0
        || region != 0u
        || offset > OS_PI5_RP1_AUDIO_OUT_REGION_SIZE - sizeof(u32)
        || (offset & 3u) != 0u
        || value == (u32 *)0) {
        return 0;
    }
    ++model->read_calls;
    if (model->read_calls == model->fail_read_call) {
        return 0;
    }
    *value = model->registers[offset / sizeof(u32)];
    return 1;
}

static int rp1_audio_out_model_write32(
    void *context,
    u32 region,
    u32 offset,
    u32 value
)
{
    rp1_audio_out_register_model *model =
        (rp1_audio_out_register_model *)context;
    if (model == (rp1_audio_out_register_model *)0
        || region != 0u
        || offset > OS_PI5_RP1_AUDIO_OUT_REGION_SIZE - sizeof(u32)
        || (offset & 3u) != 0u) {
        return 0;
    }
    ++model->write_calls;
    if (model->write_calls <= 32u) {
        model->write_offsets[model->write_calls - 1u] = offset;
        model->write_values[model->write_calls - 1u] = value;
    }
    if (model->write_calls == model->fail_write_call) {
        return 0;
    }
    model->registers[offset / sizeof(u32)] = value;
    return 1;
}

