static int bcm2712_sd_gpio_map(
    void *context,
    u64 physical_address,
    u32 size,
    volatile u32 **mapped_base
)
{
    bcm2712_sd_gpio_model *model =
        (bcm2712_sd_gpio_model *)context;
    if (model == (bcm2712_sd_gpio_model *)0
        || mapped_base == (volatile u32 **)0
        || physical_address != model->address
        || size != OS_BCM2712_AON_GPIO_REGION_SIZE) {
        return 0;
    }
    ++model->map_calls;
    *mapped_base = model->registers;
    return 1;
}

static void bcm2712_sd_gpio_unmap(
    void *context,
    volatile u32 *mapped_base,
    u32 size
)
{
    bcm2712_sd_gpio_model *model =
        (bcm2712_sd_gpio_model *)context;
    if (model != (bcm2712_sd_gpio_model *)0
        && mapped_base == model->registers
        && size == OS_BCM2712_AON_GPIO_REGION_SIZE) {
        ++model->unmap_calls;
    }
}

static int bcm2712_sd_gpio_read32(
    void *context,
    u32 region,
    u32 offset,
    u32 *value
)
{
    bcm2712_sd_gpio_model *model =
        (bcm2712_sd_gpio_model *)context;
    if (model == (bcm2712_sd_gpio_model *)0 || region != 0u
        || value == (u32 *)0 || (offset & 3u) != 0u
        || offset > OS_BCM2712_AON_GPIO_REGION_SIZE - sizeof(u32)) {
        return 0;
    }
    ++model->read_calls;
    if (model->fail_read_call == model->read_calls) {
        return 0;
    }
    if (model->remove_card_on_read_call == model->read_calls) {
        model->registers[
            OS_BCM2712_AON_GPIO_DATA_OFFSET / sizeof(u32)] |= 1u << 5;
    }
    *value = model->registers[offset / sizeof(u32)];
    return 1;
}

static int bcm2712_sd_gpio_write32(
    void *context,
    u32 region,
    u32 offset,
    u32 value
)
{
    bcm2712_sd_gpio_model *model =
        (bcm2712_sd_gpio_model *)context;
    if (model == (bcm2712_sd_gpio_model *)0 || region != 0u
        || (offset & 3u) != 0u
        || offset > OS_BCM2712_AON_GPIO_REGION_SIZE - sizeof(u32)) {
        return 0;
    }
    ++model->write_calls;
    if (model->fail_all_writes
        || model->fail_write_call == model->write_calls) {
        return 0;
    }
    model->registers[offset / sizeof(u32)] = value;
    return 1;
}

static int bcm2712_sd_pinctrl_map(
    void *context,
    u64 physical_address,
    u32 size,
    volatile u32 **mapped_base
)
{
    bcm2712_sd_pinctrl_model *model =
        (bcm2712_sd_pinctrl_model *)context;
    if (model == (bcm2712_sd_pinctrl_model *)0
        || mapped_base == (volatile u32 **)0) {
        return 0;
    }
    ++model->map_calls;
    if (model->fail_map_call == model->map_calls) {
        return 0;
    }
    if (physical_address == 0x7d504100ull
        && size == model->pinctrl_size) {
        *mapped_base = model->pinctrl_registers;
        return 1;
    }
    if (physical_address == 0x7d510700ull
        && size == model->aon_pinctrl_size) {
        *mapped_base = model->aon_pinctrl_registers;
        return 1;
    }
    return 0;
}

static void bcm2712_sd_pinctrl_unmap(
    void *context,
    volatile u32 *mapped_base,
    u32 size
)
{
    bcm2712_sd_pinctrl_model *model =
        (bcm2712_sd_pinctrl_model *)context;
    if (model != (bcm2712_sd_pinctrl_model *)0
        && ((mapped_base == model->pinctrl_registers
                && size == model->pinctrl_size)
            || (mapped_base == model->aon_pinctrl_registers
                && size == model->aon_pinctrl_size))) {
        ++model->unmap_calls;
    }
}

static int bcm2712_sdhci_command_read32(
    void *context,
    u32 region,
    u32 offset,
    u32 *value
)
{
    bcm2712_sdhci_command_model *model =
        (bcm2712_sdhci_command_model *)context;
    if (model == (bcm2712_sdhci_command_model *)0 || region != 0u
        || value == (u32 *)0 || (offset & 3u) != 0u
        || offset > OS_BCM2712_SDHCI_HOST_REGION_SIZE - sizeof(u32)) {
        return 0;
    }
    if (offset == OS_BCM2712_SDHCI_PRESENT_STATE) {
        *value = model->present_state;
    } else if (offset == OS_BCM2712_SDHCI_INTERRUPT_STATUS) {
        *value = model->interrupt_status;
    } else if (offset >= OS_BCM2712_SDHCI_RESPONSE0
        && offset <= OS_BCM2712_SDHCI_RESPONSE0 + 12u) {
        *value = model->response[
            (offset - OS_BCM2712_SDHCI_RESPONSE0) / sizeof(u32)];
    } else if (offset == OS_BCM2712_SDHCI_ARGUMENT) {
        *value = model->command_argument;
    } else {
        *value = model->registers[offset / sizeof(u32)];
    }
    return 1;
}

static int bcm2712_sdhci_command_write32(
    void *context,
    u32 region,
    u32 offset,
    u32 value
)
{
    bcm2712_sdhci_command_model *model =
        (bcm2712_sdhci_command_model *)context;
    if (model == (bcm2712_sdhci_command_model *)0 || region != 0u
        || (offset & 3u) != 0u
        || offset > OS_BCM2712_SDHCI_HOST_REGION_SIZE - sizeof(u32)) {
        return 0;
    }
    if (offset == OS_BCM2712_SDHCI_INTERRUPT_STATUS) {
        model->interrupt_status &= ~value;
    } else if (offset == OS_BCM2712_SDHCI_ARGUMENT) {
        model->command_argument = value;
    } else {
        model->registers[offset / sizeof(u32)] = value;
    }
    return 1;
}

static int bcm2712_sdhci_command_read16(
    void *context,
    u32 region,
    u32 offset,
    u16 *value
)
{
    bcm2712_sdhci_command_model *model =
        (bcm2712_sdhci_command_model *)context;
    if (model == (bcm2712_sdhci_command_model *)0 || region != 0u
        || value == (u16 *)0 || (offset & 1u) != 0u
        || offset > OS_BCM2712_SDHCI_HOST_REGION_SIZE - sizeof(u16)) {
        return 0;
    }
    *value = (u16)(model->registers[offset / sizeof(u32)] >> ((offset & 2u) * 8u));
    return 1;
}

static int bcm2712_sdhci_command_write16(
    void *context,
    u32 region,
    u32 offset,
    u16 value
)
{
    bcm2712_sdhci_command_model *model =
        (bcm2712_sdhci_command_model *)context;
    if (model == (bcm2712_sdhci_command_model *)0 || region != 0u
        || (offset & 1u) != 0u
        || offset > OS_BCM2712_SDHCI_HOST_REGION_SIZE - sizeof(u16)) {
        return 0;
    }
    if (offset == OS_BCM2712_SDHCI_COMMAND) {
        model->last_command = value;
        if (model->script_length != 0u) {
            u32 cursor = model->script_cursor;
            if (cursor >= model->script_length
                || model->scripted_commands[cursor]
                    != (u8)(value >> 8)) {
                model->script_failed = 1u;
                model->fail_command = 1u;
            } else {
                for (u32 i = 0; i < 4u; ++i) {
                    model->response[i] =
                        model->scripted_responses[cursor][i];
                }
                ++model->script_cursor;
            }
        }
        if (model->fail_command) {
            model->interrupt_status |= 0x00018000u;
        } else if (model->complete_command) {
            model->interrupt_status |= OS_BCM2712_SDHCI_INT_RESPONSE;
        }
    } else {
        u32 shift = (offset & 2u) * 8u;
        u32 mask = 0xffffu << shift;
        model->registers[offset / sizeof(u32)] =
            (model->registers[offset / sizeof(u32)] & ~mask)
            | ((u32)value << shift);
    }
    return 1;
}

static int bcm2712_sdhci_pio_read8(
    void *context,
    u32 region,
    u32 offset,
    u8 *value
)
{
    bcm2712_sdhci_pio_model *model =
        (bcm2712_sdhci_pio_model *)context;
    if (model == (bcm2712_sdhci_pio_model *)0 || region != 0u
        || offset >= sizeof(model->registers)
        || value == (u8 *)0) {
        return 0;
    }
    *value = model->registers[offset];
    return 1;
}

static int bcm2712_sdhci_pio_write8(
    void *context,
    u32 region,
    u32 offset,
    u8 value
)
{
    bcm2712_sdhci_pio_model *model =
        (bcm2712_sdhci_pio_model *)context;
    if (model == (bcm2712_sdhci_pio_model *)0 || region != 0u
        || offset >= sizeof(model->registers)) {
        return 0;
    }
    model->registers[offset] = value;
    if (offset == OS_BCM2712_SDHCI_SOFTWARE_RESET
        && (value & 0x04u) != 0u) {
        ++model->reset_count;
        if (!model->reset_stuck) {
            model->registers[offset] &= (u8)~0x04u;
        }
    }
    return 1;
}

static int bcm2712_sdhci_pio_read16(
    void *context,
    u32 region,
    u32 offset,
    u16 *value
)
{
    bcm2712_sdhci_pio_model *model =
        (bcm2712_sdhci_pio_model *)context;
    if (model == (bcm2712_sdhci_pio_model *)0 || region != 0u
        || offset > sizeof(model->registers) - sizeof(u16)
        || (offset & 1u) != 0u || value == (u16 *)0) {
        return 0;
    }
    *value = (u16)model->registers[offset]
        | ((u16)model->registers[offset + 1u] << 8);
    return 1;
}

static int bcm2712_sdhci_pio_write16(
    void *context,
    u32 region,
    u32 offset,
    u16 value
)
{
    bcm2712_sdhci_pio_model *model =
        (bcm2712_sdhci_pio_model *)context;
    if (model == (bcm2712_sdhci_pio_model *)0 || region != 0u
        || offset > sizeof(model->registers) - sizeof(u16)
        || (offset & 1u) != 0u) {
        return 0;
    }
    ++model->write16_calls;
    if (model->fail_write16_call == model->write16_calls) {
        return 0;
    }
    model->registers[offset] = (u8)value;
    model->registers[offset + 1u] = (u8)(value >> 8);
    if (offset == OS_BCM2712_SDHCI_COMMAND) {
        model->command = value;
        model->interrupt_status |= OS_BCM2712_SDHCI_INT_RESPONSE
            | model->data_ready_status;
    }
    return 1;
}

static int bcm2712_sdhci_pio_read32(
    void *context,
    u32 region,
    u32 offset,
    u32 *value
)
{
    bcm2712_sdhci_pio_model *model =
        (bcm2712_sdhci_pio_model *)context;
    if (model == (bcm2712_sdhci_pio_model *)0 || region != 0u
        || offset > sizeof(model->registers) - sizeof(u32)
        || (offset & 3u) != 0u || value == (u32 *)0) {
        return 0;
    }
    if (offset == OS_BCM2712_SDHCI_INTERRUPT_STATUS) {
        *value = model->interrupt_status;
        if (model->data_error && model->response_acknowledged) {
            *value |= 0x00008000u;
        }
        return 1;
    }
    if (offset == OS_BCM2712_SDHCI_PRESENT_STATE) {
        *value = model->present_state;
        return 1;
    }
    if (offset == OS_BCM2712_SDHCI_BUFFER) {
        ++model->buffer_operations;
        if (model->fail_buffer_operation == model->buffer_operations
            || model->fifo_index >= model->fifo_count) {
            return 0;
        }
        *value = model->fifo[model->fifo_index++];
        return 1;
    }
    *value = (u32)model->registers[offset]
        | ((u32)model->registers[offset + 1u] << 8)
        | ((u32)model->registers[offset + 2u] << 16)
        | ((u32)model->registers[offset + 3u] << 24);
    return 1;
}

static int bcm2712_sdhci_pio_write32(
    void *context,
    u32 region,
    u32 offset,
    u32 value
)
{
    bcm2712_sdhci_pio_model *model =
        (bcm2712_sdhci_pio_model *)context;
    if (model == (bcm2712_sdhci_pio_model *)0 || region != 0u
        || offset > sizeof(model->registers) - sizeof(u32)
        || (offset & 3u) != 0u) {
        return 0;
    }
    if (offset == OS_BCM2712_SDHCI_INTERRUPT_STATUS) {
        model->interrupt_status &= ~value;
        if ((value & OS_BCM2712_SDHCI_INT_RESPONSE) != 0u) {
            model->response_acknowledged = 1u;
        }
        if ((value & (OS_BCM2712_SDHCI_INT_SPACE_AVAILABLE
                | OS_BCM2712_SDHCI_INT_DATA_AVAILABLE)) != 0u
            && model->data_end_after_ack) {
            model->interrupt_status |= OS_BCM2712_SDHCI_INT_DATA_END;
        }
        return 1;
    }
    if (offset == OS_BCM2712_SDHCI_ARGUMENT) {
        model->command_argument = value;
        return 1;
    }
    if (offset == OS_BCM2712_SDHCI_BUFFER) {
        ++model->buffer_operations;
        if (model->fail_buffer_operation == model->buffer_operations
            || model->fifo_count
                >= OS_STORAGE_BLOCK_SIZE / sizeof(u32)) {
            return 0;
        }
        model->fifo[model->fifo_count++] = value;
        return 1;
    }
    model->registers[offset] = (u8)value;
    model->registers[offset + 1u] = (u8)(value >> 8);
    model->registers[offset + 2u] = (u8)(value >> 16);
    model->registers[offset + 3u] = (u8)(value >> 24);
    return 1;
}

static void bcm2712_sdhci_script_long_response(
    bcm2712_sdhci_command_model *model,
    u32 script_index,
    const u32 canonical_response[4]
)
{
    u32 words[4];
    words[0] = canonical_response[0] >> 8;
    words[1] = (canonical_response[0] << 24)
        | (canonical_response[1] >> 8);
    words[2] = (canonical_response[1] << 24)
        | (canonical_response[2] >> 8);
    words[3] = (canonical_response[2] << 24)
        | (canonical_response[3] >> 8);
    for (u32 i = 0; i < 4u; ++i) {
        model->scripted_responses[script_index][3u - i] = words[i];
    }
}

static int bcm2712_sdhci_map(
    void *context,
    u64 physical_address,
    u32 size,
    volatile u32 **mapped_base
)
{
    bcm2712_sdhci_mapper_model *model =
        (bcm2712_sdhci_mapper_model *)context;
    if (model == (bcm2712_sdhci_mapper_model *)0
        || mapped_base == (volatile u32 **)0) {
        return 0;
    }
    u32 index = model->map_calls++;
    if (index >= 2u
        || model->fail_map_call == model->map_calls
        || physical_address != model->addresses[index]
        || size != model->sizes[index]) {
        return 0;
    }
    *mapped_base = &model->registers[
        index == 0u ? 0u : 0x300u / sizeof(u32)];
    return 1;
}

static void bcm2712_sdhci_unmap(
    void *context,
    volatile u32 *mapped_base,
    u32 size
)
{
    bcm2712_sdhci_mapper_model *model =
        (bcm2712_sdhci_mapper_model *)context;
    if (model == (bcm2712_sdhci_mapper_model *)0) {
        return;
    }
    ++model->unmap_calls;
    u32 index = mapped_base == &model->registers[0]
        ? 0u
        : (mapped_base == &model->registers[0x300u / sizeof(u32)]
            ? 1u : 2u);
    if (index >= 2u || size != model->sizes[index]) {
        model->unmap_error = 1u;
    }
}
