static int hdmi_mapper_model_map(
    void *context,
    u64 physical_address,
    u32 size,
    volatile u32 **mapped_base
)
{
    hdmi_mapper_model *model = (hdmi_mapper_model *)context;
    if (model == (hdmi_mapper_model *)0
        || mapped_base == (volatile u32 **)0
        || model->map_calls >= model->expected_count) {
        return 0;
    }
    u32 index = model->map_calls++;
    *mapped_base = (volatile u32 *)0;
    if (physical_address != model->addresses[index]
        || size != model->sizes[index]) {
        model->invalid_call = 1u;
        return 0;
    }
    if (model->map_calls == model->fail_on_call) {
        return 0;
    }
    model->mapped[index] = 1u;
    *mapped_base = model->regions[index];
    return 1;
}

static void hdmi_mapper_model_unmap(
    void *context,
    volatile u32 *mapped_base,
    u32 size
)
{
    hdmi_mapper_model *model = (hdmi_mapper_model *)context;
    if (model == (hdmi_mapper_model *)0 || mapped_base == 0) {
        return;
    }
    for (u32 i = 0u; i < model->expected_count; ++i) {
        if (model->regions[i] == mapped_base
            && model->sizes[i] == size && model->mapped[i]
            && !model->unmapped[i]) {
            model->unmapped[i] = 1u;
            ++model->unmap_calls;
            return;
        }
    }
    model->invalid_call = 1u;
}

