static int dma_model_release(
    void *context,
    void *virtual_address,
    usize size
)
{
    dma_allocator_model *model = (dma_allocator_model *)context;
    if (model == (dma_allocator_model *)0 || model->fail_release
        || virtual_address != g_dma_memory || size == 0
        || size > sizeof(g_dma_memory)) {
        return 0;
    }
    ++model->release_calls;
    return 1;
}

