static int rp1_gem_dma_model_allocate(
    void *context,
    usize size,
    usize alignment,
    void **virtual_address,
    u64 *system_address
)
{
    rp1_gem_dma_allocator_model *model =
        (rp1_gem_dma_allocator_model *)context;
    if (model == (rp1_gem_dma_allocator_model *)0
        || virtual_address == (void **)0
        || system_address == (u64 *)0
        || size == 0u || alignment == 0u
        || (alignment & (alignment - 1u)) != 0u) {
        return 0;
    }

    ++model->allocate_calls;
    if (model->allocate_calls == model->fail_allocate_call
        || model->record_count >= 4u) {
        return 0;
    }

    usize offset = model->next_offset;
    if (model->force_alias && model->record_count != 0u) {
        offset = (usize)((usize)model->addresses[0]
            - (usize)g_rp1_gem_dma_memory);
    } else {
        usize base = (usize)g_rp1_gem_dma_memory;
        if (offset > ~(usize)0 - base
            || base + offset > ~(usize)0 - (alignment - 1u)) {
            return 0;
        }
        usize aligned = (base + offset + alignment - 1u)
            & ~(alignment - 1u);
        offset = aligned - base;
    }
    if (offset > sizeof(g_rp1_gem_dma_memory)
        || size > sizeof(g_rp1_gem_dma_memory) - offset) {
        return 0;
    }

    u64 physical_base = model->dma_parent_base;
    *virtual_address = &g_rp1_gem_dma_memory[offset];
    *system_address = physical_base + (u64)offset;
    model->addresses[model->record_count] = *virtual_address;
    model->sizes[model->record_count] = size;
    model->released[model->record_count] = 0u;
    ++model->record_count;
    if (!model->force_alias) {
        model->next_offset = offset + size;
    }
    return 1;
}

static int rp1_gem_dma_model_release(
    void *context,
    void *virtual_address,
    usize size
)
{
    rp1_gem_dma_allocator_model *model =
        (rp1_gem_dma_allocator_model *)context;
    if (model == (rp1_gem_dma_allocator_model *)0
        || virtual_address == (void *)0 || size == 0u) {
        return 0;
    }
    ++model->release_calls;
    if (model->release_calls == model->fail_release_call) {
        return 0;
    }
    for (usize i = 0; i < model->record_count; ++i) {
        if (!model->released[i]
            && model->addresses[i] == virtual_address
            && model->sizes[i] == size) {
            model->released[i] = 1u;
            return 1;
        }
    }
    return 0;
}

static int rp1_gem_dma_model_sync(
    void *context,
    void *virtual_address,
    u64 system_address,
    usize size
)
{
    rp1_gem_dma_allocator_model *model =
        (rp1_gem_dma_allocator_model *)context;
    if (model == (rp1_gem_dma_allocator_model *)0
        || virtual_address == (void *)0 || system_address == 0u
        || size == 0u) {
        return 0;
    }
    ++model->sync_calls;
    return model->sync_calls != model->fail_sync_call;
}

static int gicv2_model_read32(
    void *context,
    u32 region,
    u32 offset,
    u32 *value
)
{
    gicv2_register_model *model = (gicv2_register_model *)context;
    if (model == (gicv2_register_model *)0 || region >= 2u
        || (offset & 3u) != 0 || offset > 0x1000u - sizeof(u32)
        || value == (u32 *)0) {
        return 0;
    }
    if (region == 1u && offset == 0x0cu) {
        *value = model->pending_acknowledge;
        model->pending_acknowledge = 1023u;
        return 1;
    }
    *value = model->regions[region][offset / sizeof(u32)];
    return 1;
}

static int gicv2_model_write32(
    void *context,
    u32 region,
    u32 offset,
    u32 value
)
{
    gicv2_register_model *model = (gicv2_register_model *)context;
    if (model == (gicv2_register_model *)0
        || region >= 2u || (offset & 3u) != 0
        || offset > 0x1000u - sizeof(u32)) {
        return 0;
    }
    if (model->fail_write) {
        return 0;
    }
    if (region == 0u && offset >= 0x100u && offset < 0x180u) {
        model->regions[0][offset / 4u] |= value;
        if (model->dispatch_on_enable
            && model->dispatch_gic != (os_pi5_gicv2 *)0
            && offset == 0x100u
                + (OS_PI5_BCM2711_AON_L2_PARENT_INTERRUPT / 32u)
                    * sizeof(u32)
            && (value & (1u
                << (OS_PI5_BCM2711_AON_L2_PARENT_INTERRUPT % 32u))) != 0u) {
            model->pending_acknowledge = model->dispatch_interrupt;
            model->dispatch_result = os_pi5_gicv2_dispatch(
                model->dispatch_gic);
            model->dispatch_on_enable = 0u;
        }
        return 1;
    }
    if (region == 0u && offset >= 0x180u && offset < 0x200u) {
        model->regions[0][offset / 4u] = value;
        model->regions[0][(offset - 0x80u) / 4u] &= ~value;
        return 1;
    }
    if (region == 1u && offset == 0x10u) {
        model->last_eoi = value;
        ++model->eoi_count;
    }
    model->regions[region][offset / sizeof(u32)] = value;
    return 1;
}

static void gicv2_test_handler(void *context, u32 interrupt_id)
{
    u32 *count = (u32 *)context;
    if (count != (u32 *)0) {
        ++*count;
    }
    g_gic_handler_interrupt = interrupt_id;
    ++g_gic_handler_count;
}

static void clear_test_bytes(void *memory, usize size)
{
    volatile u8 *bytes = (volatile u8 *)memory;
    for (usize i = 0; i < size; ++i) {
        bytes[i] = 0;
    }
}

static void copy_test_bytes(void *destination, const void *source, usize size)
{
    volatile u8 *destination_bytes = (volatile u8 *)destination;
    const volatile u8 *source_bytes = (const volatile u8 *)source;
    for (usize i = 0; i < size; ++i) {
        destination_bytes[i] = source_bytes[i];
    }
}

static int test_bytes_equal(
    const void *left,
    const void *right,
    usize size
)
{
    const u8 *left_bytes = (const u8 *)left;
    const u8 *right_bytes = (const u8 *)right;
    for (usize i = 0u; i < size; ++i) {
        if (left_bytes[i] != right_bytes[i]) {
            return 0;
        }
    }
    return 1;
}

static int xhci_model_read32(
    void *context,
    u32 region,
    u32 offset,
    u32 *value
)
{
    xhci_register_model *model = (xhci_register_model *)context;
    if (model == (xhci_register_model *)0 || region != 0u
        || value == (u32 *)0 || (offset & 3u) != 0u
        || offset > sizeof(model->registers) - sizeof(u32)
        || (model->fail_read && offset == model->fail_read_offset)
        || model->fail_read_call == model->read_calls + 1u) {
        return 0;
    }
    ++model->read_calls;
    *value = model->registers[offset / sizeof(u32)];
    return 1;
}

static int xhci_model_write32(
    void *context,
    u32 region,
    u32 offset,
    u32 value
)
{
    xhci_register_model *model = (xhci_register_model *)context;
    if (model == (xhci_register_model *)0 || region != 0u
        || (offset & 3u) != 0u
        || offset > sizeof(model->registers) - sizeof(u32)) {
        return 0;
    }
    ++model->write_calls;
    model->last_write_offset = offset;
    model->last_write_value = value;
    if (model->fail_write_call == model->write_calls
        || model->fail_write_call2 == model->write_calls) {
        return 0;
    }
    if (model->emulate_port_reset
        && offset == model->port_reset_offset) {
        u32 *portsc = &model->registers[offset / sizeof(u32)];
        u32 portsc_value = *portsc;
        portsc_value &= ~(value & OS_PI5_XHCI_PORTSC_CHANGE_MASK);
        portsc_value = (portsc_value
                & ~(OS_PI5_XHCI_PORTSC_POWER
                    | OS_PI5_XHCI_PORTSC_INDICATOR_MASK
                    | OS_PI5_XHCI_PORTSC_WAKE_MASK))
            | (value & (OS_PI5_XHCI_PORTSC_POWER
                | OS_PI5_XHCI_PORTSC_INDICATOR_MASK
                | OS_PI5_XHCI_PORTSC_WAKE_MASK));
        if (model->port_reset_bit != 0u
            && (value & model->port_reset_bit) != 0u) {
            if (model->suppress_port_reset) {
                portsc_value |= model->port_reset_bit;
            } else {
                portsc_value &= ~model->port_reset_bit;
                portsc_value |= model->port_reset_change_bit
                    | OS_PI5_XHCI_PORTSC_ENABLED;
            }
        }
        *portsc = portsc_value;
    } else {
        model->registers[offset / sizeof(u32)] = value;
    }
    if (model->emulate_run_stop && offset == 0x20u) {
        u32 *status =
            &model->registers[(offset + sizeof(u32)) / sizeof(u32)];
        if ((value & OS_PI5_XHCI_USBCMD_RUN) != 0u) {
            if (!model->suppress_run_transition) {
                *status &= ~OS_PI5_XHCI_USBSTS_HALT;
            }
        } else {
            *status |= OS_PI5_XHCI_USBSTS_HALT;
        }
    }
    return 1;
}

static int xhci_startup_check(
    void *context,
    u32 poll_limit,
    u32 check_bit
)
{
    xhci_startup_check_model *model =
        (xhci_startup_check_model *)context;
    if (model == (xhci_startup_check_model *)0 || poll_limit == 0u) {
        return 0;
    }
    if (model->poll_limit != 0u && model->poll_limit != poll_limit) {
        model->invalid_limit = 1u;
    }
    model->poll_limit = poll_limit;
    model->checked_mask |= check_bit;
    return model->failed_check != check_bit;
}

