static void xhci_model_init_valid(xhci_register_model *model)
{
    clear_test_bytes(model, sizeof(*model));
    model->registers[OS_RP1_DWC3_GSNPSID / sizeof(u32)] =
        (OS_RP1_DWC3_ID_DWC3 << 16) | 0x330au;
    model->registers[OS_RP1_DWC3_GCTL / sizeof(u32)] =
        OS_RP1_DWC3_GCTL_PRTCAP_HOST;
    model->registers[OS_PI5_XHCI_CAPABILITY_BASE / sizeof(u32)] =
        (0x0100u << 16) | OS_PI5_XHCI_CAPABILITY_MIN_SIZE;
    model->registers[OS_PI5_XHCI_HCSPARAMS1 / sizeof(u32)] =
        8u | (4u << 8) | (4u << 24);
    model->registers[OS_PI5_XHCI_HCCPARAMS1 / sizeof(u32)] =
        (0x20u << 16) | (1u << 2);
    model->registers[OS_PI5_XHCI_DBOFF / sizeof(u32)] = 0x800u;
    model->registers[OS_PI5_XHCI_RTSOFF / sizeof(u32)] = 0x1000u;
    model->registers[OS_PI5_XHCI_HCCPARAMS2 / sizeof(u32)] = 0x1234u;
    model->registers[
        (OS_PI5_XHCI_CAPABILITY_MIN_SIZE + 8u) / sizeof(u32)] = 1u;
}

static int xhci_event_dispatch_handler(
    void *context,
    const os_pi5_xhci_trb *event
)
{
    xhci_event_handler_model *model =
        (xhci_event_handler_model *)context;
    if (model == (xhci_event_handler_model *)0
        || event == (const os_pi5_xhci_trb *)0 || model->fail) {
        return 0;
    }
    ++model->calls;
    return 1;
}

static int xhci_event_reentrancy_handler(
    void *context,
    const os_pi5_xhci_trb *event
)
{
    xhci_event_reentrancy_model *model =
        (xhci_event_reentrancy_model *)context;
    if (model == (xhci_event_reentrancy_model *)0
        || event == (const os_pi5_xhci_trb *)0) {
        return 0;
    }

    xhci_event_handler_model nested_handler = {0};
    u32 nested_events_processed = ~(u32)0;
    model->nested_result = os_pi5_xhci_event_dispatch(
        model->allocator, model->resources, model->capabilities,
        model->rings, xhci_event_dispatch_handler, &nested_handler,
        1u, &nested_events_processed);
    model->nested_events_processed = nested_events_processed;
    model->rings_release_rejected = (u8)(
        !os_pi5_xhci_dma_rings_release(model->allocator, model->rings));
    ++model->calls;
    return 1;
}

static int xhci_dma_model_allocate(
    void *context,
    usize size,
    usize alignment,
    void **virtual_address,
    u64 *system_address
)
{
    xhci_dma_allocator_model *model =
        (xhci_dma_allocator_model *)context;
    if (model == (xhci_dma_allocator_model *)0
        || virtual_address == (void **)0
        || system_address == (u64 *)0
        || size == 0u || size > sizeof(g_xhci_dma_memory[0])
        || alignment == 0u || alignment > sizeof(g_xhci_dma_memory[0])) {
        return 0;
    }
    if (model->try_release_during_allocate
        && !model->release_during_allocate_attempted) {
        model->release_during_allocate_attempted = 1u;
        model->release_during_allocate_succeeded = (u8)
            os_pi5_xhci_dma_rings_release(
                model->allocator, model->rings);
    }
    ++model->allocate_calls;
    if (model->allocate_calls == model->fail_allocate_call) {
        return 0;
    }
    u32 slot = model->alias_allocations
        ? 0u : model->allocate_calls - 1u;
    if (slot >= g_xhci_dma_model_max_slots) {
        return 0;
    }
    *virtual_address = g_xhci_dma_memory[slot];
    *system_address = model->system_base + (u64)slot * 0x1000u;
    return 1;
}

static int xhci_dma_model_release(
    void *context,
    void *virtual_address,
    usize size
)
{
    xhci_dma_allocator_model *model =
        (xhci_dma_allocator_model *)context;
    if (model == (xhci_dma_allocator_model *)0 || model->fail_release
        || virtual_address == (void *)0 || size == 0u
        || size > sizeof(g_xhci_dma_memory[0])) {
        return 0;
    }
    if (model->try_allocate_during_release
        && !model->allocate_during_release_attempted) {
        model->allocate_during_release_attempted = 1u;
        model->allocate_during_release_succeeded = (u8)
            os_pi5_xhci_dma_rings_allocate(
                model->node, model->allocator, model->address_flags,
                model->capabilities, model->rings);
    }
    for (u32 slot = 0u;
        slot < sizeof(g_xhci_dma_memory) / sizeof(g_xhci_dma_memory[0]);
        ++slot) {
        if (virtual_address == g_xhci_dma_memory[slot]) {
            ++model->release_calls;
            return 1;
        }
    }
    return 0;
}

static int xhci_dma_model_sync(
    void *context,
    void *virtual_address,
    u64 system_address,
    usize size
)
{
    xhci_dma_allocator_model *model =
        (xhci_dma_allocator_model *)context;
    if (model == (xhci_dma_allocator_model *)0
        || virtual_address == (void *)0 || system_address == 0u
        || size == 0u || size > sizeof(g_xhci_dma_memory[0])) {
        return 0;
    }
    int address_matches = 0;
    for (u32 slot = 0u;
        slot < sizeof(g_xhci_dma_memory) / sizeof(g_xhci_dma_memory[0]);
        ++slot) {
        if (virtual_address == g_xhci_dma_memory[slot]
            && system_address
                == model->system_base + (u64)slot * 0x1000u) {
            address_matches = 1;
            break;
        }
    }
    if (!address_matches) {
        return 0;
    }
    if (model->try_release_during_sync
        && !model->release_during_sync_attempted) {
        model->release_during_sync_attempted = 1u;
        model->release_during_sync_succeeded = (u8)
            os_pi5_xhci_dma_rings_release(
                model->allocator, model->rings);
    }
    ++model->sync_calls;
    return model->sync_calls != model->fail_sync_call;
}

