    tree.nodes[0].regions[0].size = sizeof(clock_registers);
    tree.nodes[0].regions[0].translated = 1u;
    tree.nodes[0].clock_reference_count = 1u;
    tree.nodes[0].clock_references[0].provider_index = 2u;
    tree.nodes[1].clock_reference_count = 1u;
    tree.nodes[1].clock_references[0].provider_index = 0u;
