    bcm2712_platform_mapper_model mapper_model = {
        .addresses = {tree.nodes[0].regions[0].address, 0u, 0u},
        .sizes = {(u32)sizeof(clock_registers), 0u, 0u},
        .bases = {clock_registers, (volatile u32 *)0, (volatile u32 *)0},
    };
